<!doctype html>
<html lang="zh-Hant">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>mori — 選物購物網站</title>
  <link rel="stylesheet" href="styles.css">
  <link rel="stylesheet" href="auth.css">
  <link rel="stylesheet" href="status.css">
  <!--
    :root { --ink:#1d2a2c; --muted:#6b7879; --paper:#faf9f5; --sage:#dbe5d8; --mint:#eff4ed; --coral:#df7058; --line:#e7e5de; --white:#fff; }
    * { box-sizing:border-box; } body { margin:0; color:var(--ink); background:var(--paper); font-family:"Noto Sans TC","Microsoft JhengHei",Arial,sans-serif; } button,input { font:inherit; } button { cursor:pointer; }
    .top { background:#203735; color:#fff; padding:10px 5%; text-align:center; font-size:13px; letter-spacing:.04em; } header { background:rgba(250,249,245,.94); position:sticky; top:0; z-index:4; border-bottom:1px solid var(--line); }
    .nav { max-width:1180px; margin:auto; padding:17px 22px; display:flex; gap:28px; align-items:center; } .brand { font:700 26px Georgia,serif; letter-spacing:-.08em; text-decoration:none; color:var(--ink); }
    .navlinks { display:flex; gap:20px; flex:1; margin-left:18px; } .navlinks a { color:var(--ink); font-size:14px; text-decoration:none; } .tools { display:flex; gap:14px; align-items:center; } .icon-btn { border:0; background:transparent; color:var(--ink); padding:5px; font-size:19px; position:relative; } .count { position:absolute; right:-4px; top:-4px; background:var(--coral); color:#fff; font:11px Arial; min-width:17px; height:17px; border-radius:9px; padding:2px; }
    .search { display:flex; align-items:center; border-bottom:1px solid var(--ink); gap:7px; } .search input { width:116px; border:0; outline:0; background:transparent; padding:6px 0; font-size:13px; }
    main { max-width:1180px; margin:auto; padding:0 22px 70px; } .hero { min-height:440px; display:grid; grid-template-columns:1fr 1.12fr; margin:30px 0 64px; background:var(--sage); overflow:hidden; } .hero-copy { padding:70px 12%; align-self:center; } .eyebrow { color:#5b7169; font-size:13px; letter-spacing:.12em; } h1 { font:500 clamp(38px,5vw,66px)/1.08 Georgia,"Times New Roman",serif; margin:13px 0 20px; } .hero p { color:#405150; line-height:1.8; margin-bottom:29px; } .primary { background:var(--ink); color:white; border:0; padding:13px 21px; font-size:14px; } .hero-art { min-height:340px; position:relative; background:linear-gradient(135deg,#bccbb8,#dfe7d9); overflow:hidden; } .circle { width:340px;height:340px;border-radius:50%;background:#eef1e5; position:absolute; right:11%; top:10%; } .vase { width:136px;height:210px;background:#c1775f;border-radius:58% 58% 36% 36%;position:absolute;right:31%;top:31%;box-shadow:inset -20px -12px #ac634f; } .vase:before { content:"";position:absolute;width:61px;height:91px;border-radius:50%;background:#c1775f;top:-60px;left:38px; transform:rotate(-24deg); } .branch { position:absolute; height:148px; width:3px;background:#47614d;right:44%;top:11%; transform:rotate(-12deg); } .branch:after,.branch:before { content:""; position:absolute; height:45px;width:16px; border-radius:90% 0 90% 0;background:#56775c; } .branch:before{top:21px;left:-14px;transform:rotate(-40deg)} .branch:after{top:71px;left:2px;transform:rotate(40deg)}
    .section-head { display:flex; justify-content:space-between; align-items:end; margin-bottom:24px; } h2 { font:500 30px Georgia,serif; margin:0; } .text-link { border:0; background:transparent; text-decoration:underline; color:var(--ink); font-size:14px; } .categories { display:grid; grid-template-columns:repeat(4,1fr); gap:16px; margin-bottom:75px; } .category { text-align:left; border:0; background:transparent; padding:0; } .category-img { height:154px; display:flex; align-items:center; justify-content:center; font:52px Georgia,serif; color:#fff; margin-bottom:12px; } .category:nth-child(1) .category-img{background:#c39d82}.category:nth-child(2) .category-img{background:#9daea0}.category:nth-child(3) .category-img{background:#b6a78d}.category:nth-child(4) .category-img{background:#c97966}.category strong { font-size:15px; font-weight:500; } .category span { display:block; font-size:13px; color:var(--muted); margin-top:4px; }
    .product-section { scroll-margin-top:90px; } .filters { display:flex; gap:9px; margin:-5px 0 23px; flex-wrap:wrap; } .filter { border:1px solid var(--line); background:transparent; padding:8px 14px; font-size:13px; } .filter.active,.filter:hover { background:var(--ink); color:#fff; border-color:var(--ink); } .products { display:grid; grid-template-columns:repeat(4,1fr); gap:18px; } .product { background:var(--white); padding-bottom:15px; position:relative; } .product.hide { display:none; } .product-visual { height:210px; display:flex; align-items:center; justify-content:center; font:64px Georgia,serif; position:relative; } .p1{background:#e9e1d5}.p2{background:#dfe8dd}.p3{background:#eee8df}.p4{background:#eadbd6}.p5{background:#e6e9e2}.p6{background:#e4dfd3}.p7{background:#eeded3}.p8{background:#dce5e2} .heart { position:absolute;right:10px;top:10px;border:0;background:rgba(255,255,255,.72);border-radius:50%;width:33px;height:33px;font-size:17px;color:var(--ink); } .heart.liked{color:var(--coral)} .product-info { padding:14px 14px 0; } .product-type{font-size:12px;color:var(--muted)} .product-row { display:flex;justify-content:space-between;gap:8px;align-items:start;margin-top:6px; } .product-name { font-size:14px;font-weight:500;line-height:1.35; } .price{font-size:14px;white-space:nowrap}.add { margin:12px 14px 0;width:calc(100% - 28px);background:var(--mint);border:0;padding:9px;font-size:13px;color:var(--ink); } .add:hover{background:var(--sage)}
    .newsletter { margin-top:74px; padding:42px; background:#203735; color:#fff; display:flex; justify-content:space-between; align-items:center; gap:25px; } .newsletter h2{font-size:29px}.newsletter p{margin:8px 0 0;color:#cdd9d3;font-size:14px}.subscribe { display:flex;background:white;padding:4px;min-width:330px; } .subscribe input{border:0;outline:0;padding:9px;flex:1;min-width:0}.subscribe button{border:0;background:var(--coral);color:white;padding:10px 15px;font-size:13px}
    footer { border-top:1px solid var(--line); padding:29px 5%; display:flex; justify-content:space-between; color:var(--muted); font-size:13px; } #notice { opacity:0; transition:opacity .25s; position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;padding:12px 18px;z-index:7;font-size:14px; } #notice.show {opacity:1;} .mobile-menu{display:none}
    @media(max-width:740px){.nav{padding:14px 18px;gap:13px}.navlinks{display:none}.mobile-menu{display:block}.search input{width:72px}.hero{grid-template-columns:1fr;margin:18px 0 43px}.hero-copy{padding:50px 28px}.hero-art{min-height:260px}.vase{transform:scale(.8);transform-origin:center bottom;right:27%;top:26%}.circle{transform:scale(.8);right:4%;top:-3%}.categories,.products{grid-template-columns:repeat(2,1fr);gap:11px}.category-img{height:112px}.product-visual{height:158px}.newsletter{padding:32px 25px;display:block}.newsletter h2{font-size:27px}.subscribe{min-width:0;margin-top:24px}footer{display:block;line-height:2}.tools{gap:7px}.top{font-size:11px}}
  -->
</head>
<body>
  <div class="top">全館滿 NT$1,500 免運費｜新會員首購享 9 折</div>
  <header><nav class="nav" aria-label="主選單"><button class="icon-btn mobile-menu" aria-label="開啟選單">☰</button><a class="brand" href="#top">mori</a><div class="navlinks"><a href="#products">新品選物</a><a href="#categories">生活器物</a><a href="#products">居家香氛</a><a href="#newsletter">品牌故事</a></div><div class="tools"><label class="search" aria-label="搜尋商品">⌕<input id="search" placeholder="搜尋"></label><button id="theme-toggle" class="icon-btn" aria-label="切換明亮或黑暗主題">◐</button><button class="icon-btn" aria-label="會員登入">♙</button><button id="cart-toggle" class="icon-btn" aria-label="開啟購物車">🛍<span id="count" class="count">0</span></button></div></nav></header>
  <main id="top">
    <section class="hero"><div class="hero-copy"><div class="eyebrow">SLOW LIVING, WELL MADE</div><h1>把日常，過成喜歡的樣子。</h1><p>精選有溫度的生活器物，為每個平凡日子保留一點從容與美好。</p><a class="primary" href="#products">探索本季選物</a></div><div class="hero-art" aria-label="花器與枝葉的生活風格插畫"><div class="circle"></div><div class="branch"></div><div class="vase"></div></div></section>
    <section id="categories"><div class="section-head"><h2>依生活選物</h2><button class="text-link" data-filter="all">查看全部</button></div><div class="categories"><button class="category" data-filter="home"><div class="category-img">⌂</div><strong>居家器物</strong><span>Housewares</span></button><button class="category" data-filter="fragrance"><div class="category-img">✧</div><strong>療癒香氛</strong><span>Fragrance</span></button><button class="category" data-filter="table"><div class="category-img">◒</div><strong>餐桌風景</strong><span>Tableware</span></button><button class="category" data-filter="gift"><div class="category-img">♡</div><strong>心意選禮</strong><span>Gifts</span></button></div></section>
    <section id="products" class="product-section"><div class="section-head"><div><div class="eyebrow">CURATED FOR YOU</div><h2 style="margin-top:7px">本週人氣選物</h2></div><button class="text-link" data-filter="all">所有商品</button></div><div class="filters"><button class="filter active" data-filter="all">全部</button><button class="filter" data-filter="home">居家器物</button><button class="filter" data-filter="fragrance">療癒香氛</button><button class="filter" data-filter="table">餐桌風景</button><button class="filter" data-filter="gift">心意選禮</button></div><div class="products" id="grid">
      <article class="product" data-category="home gift" data-name="手作陶器花瓶"><div class="product-visual p1">⌇<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">居家器物</div><div class="product-row"><div class="product-name">手作陶器花瓶・奶油白</div><div class="price">NT$ 1,280</div></div></div><button class="add">加入購物車</button></article>
      <article class="product" data-category="fragrance gift" data-name="森林擴香"><div class="product-visual p2">♧<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">療癒香氛</div><div class="product-row"><div class="product-name">林間漫步擴香組</div><div class="price">NT$ 980</div></div></div><button class="add">加入購物車</button></article>
      <article class="product" data-category="table home" data-name="橡木餐盤"><div class="product-visual p3">◯<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">餐桌風景</div><div class="product-row"><div class="product-name">北歐橡木圓餐盤</div><div class="price">NT$ 760</div></div></div><button class="add">加入購物車</button></article>
      <article class="product" data-category="fragrance" data-name="晚安香氛蠟燭"><div class="product-visual p4">◉<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">療癒香氛</div><div class="product-row"><div class="product-name">晚安香氛蠟燭</div><div class="price">NT$ 680</div></div></div><button class="add">加入購物車</button></article>
      <article class="product" data-category="home" data-name="亞麻靠枕套"><div class="product-visual p5">▱<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">居家器物</div><div class="product-row"><div class="product-name">洗水亞麻靠枕套</div><div class="price">NT$ 590</div></div></div><button class="add">加入購物車</button></article>
      <article class="product" data-category="table gift" data-name="手沖咖啡組"><div class="product-visual p6">⌒<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">餐桌風景</div><div class="product-row"><div class="product-name">晨光手沖咖啡組</div><div class="price">NT$ 1,680</div></div></div><button class="add">加入購物車</button></article>
      <article class="product" data-category="gift fragrance" data-name="節日送禮組"><div class="product-visual p7">♢<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">心意選禮</div><div class="product-row"><div class="product-name">節日療癒送禮組</div><div class="price">NT$ 1,520</div></div></div><button class="add">加入購物車</button></article>
      <article class="product" data-category="home" data-name="編織收納籃"><div class="product-visual p8">⌑<button class="heart" aria-label="加入收藏">♡</button></div><div class="product-info"><div class="product-type">居家器物</div><div class="product-row"><div class="product-name">手工編織收納籃</div><div class="price">NT$ 820</div></div></div><button class="add">加入購物車</button></article>
    </div></section>
    <section class="newsletter" id="newsletter"><div><h2>把美好送進信箱</h2><p>訂閱新品與限定活動，第一時間收到生活靈感。</p></div><form class="subscribe" id="subscribe"><input type="email" aria-label="電子信箱" required placeholder="輸入你的 Email"><button>訂閱電子報</button></form></section>
  </main><footer><span>© 2026 mori select shop</span><span>購物說明　｜　退換貨政策　｜　聯絡我們</span></footer><div id="notice" role="status"></div>
  <div id="cart-backdrop" class="cart-backdrop"></div><aside id="cart-panel" class="cart-panel" aria-label="購物車" aria-hidden="true"><div class="cart-head"><h2>你的購物車</h2><button id="cart-close" class="icon-btn" aria-label="關閉購物車">×</button></div><div id="cart-items" class="cart-items"><div class="empty-cart">購物車目前沒有商品。<br>去挑一件喜歡的生活選物吧！</div></div><div class="cart-foot"><div class="cart-total"><span>小計</span><strong id="cart-total">NT$ 0</strong></div><button id="checkout" class="primary checkout">前往結帳</button></div></aside>
  <div id="auth-backdrop" class="dialog-backdrop"></div>
  <section id="auth-dialog" class="dialog" aria-hidden="true">
    <button id="auth-close" class="icon-btn dialog-close" aria-label="關閉">×</button>
    <div class="auth-tabs"><button type="button" class="auth-tab active" data-auth-mode="login">登入</button><button type="button" class="auth-tab" data-auth-mode="register">註冊</button></div>
    <p id="auth-status" class="auth-status hidden" aria-live="polite"></p><form id="auth-form"><label id="name-field" class="form-field hidden">姓名<input id="auth-name" autocomplete="name" minlength="2"></label><label class="form-field">Email<input id="auth-email" type="email" autocomplete="email" required></label><label class="form-field">密碼<input id="auth-password" type="password" autocomplete="current-password" minlength="8" required><small>至少 8 個字元</small></label><p id="auth-error" class="form-error" aria-live="polite"></p><button id="auth-submit" class="primary auth-submit">登入</button></form>
    <button id="logout" class="text-link logout hidden">登出</button>
  </section>
  <div id="checkout-backdrop" class="dialog-backdrop"></div>
  <section id="checkout-dialog" class="dialog" aria-hidden="true"><button id="checkout-close" class="icon-btn dialog-close" aria-label="關閉">×</button><h2>收件資訊</h2><form id="checkout-form"><label class="form-field">收件人<input name="recipient_name" required maxlength="80"></label><label class="form-field">聯絡電話<input name="recipient_phone" required maxlength="30"></label><label class="form-field">配送地址<textarea name="shipping_address" required maxlength="255"></textarea></label><p id="checkout-error" class="form-error" aria-live="polite"></p><button class="primary auth-submit">確認建立訂單</button></form></section>
  <script src="script.js"></script>
</body>
</html>
